     * General purpose flag, which indicates that filenames are
     * written in utf-8.
     */
    public static final int EFS_FLAG = 1 << 11;

    /**
     * Current entry.
     */
    private ZipArchiveEntry entry;

    /**
     * The file comment.
     */
    private String comment = "";

